ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def save(p,d):p.write_text(json.dumps(d,indent=2)+'\n')
def answers(folder):
 d=read(folder/'protocol.json');assert d['status']=='completed_pending_coordinator_review';rows=[]
 for q in d['questions']:
  calls=[b['toolCallRequest']for e in q['events']if e['role']=='assistant'for b in e['content']if b['type']=='toolCallRequest'];texts=[b['text'].strip()for e in q['events']if e['role']=='assistant'for b in e['content']if b['type']=='text'and b['text'].strip()]
  assert len(calls)==1 and calls[0]['name']=='project_evidence'
  rows.append({'question':q['user'],'answer':texts[-1],'seconds':q['SDK_reported_seconds'],'tool_calls':calls,'verdict':'coordinator checked against original execution and explicit scope'})
 return rows

